<script setup lang="ts">import { ref } from 'vue';import { api } from '../../api';const keyword=ref('');const items=ref<any[]>([]);async function search(){items.value=(await api.majors({keyword:keyword.value})).items}</script><template><section class="content-page"><div class="eyebrow">MAJORS / INDEX</div><h1>专业库</h1><div class="ask-row"><input v-model="keyword" placeholder="搜索专业"/><button class="primary" @click="search">检索 ↗</button></div><div class="result-grid"><article v-for="m in items" :key="m.major_id" class="feature-card"><span class="card-index">{{m.category}}</span><h2>{{m.name}}</h2><p>{{m.degree}}</p></article></div></section></template>
